type Listener = (order: Order) => void;

class OrderService {
  private listeners: Listener[] = [];

  subscribe(listener: Listener) {
    this.listeners.push(listener);
  }

  shipOrder(order: Order) {
    // ...ship the order...

    // Broadcast — OrderService doesn't know who's listening
    this.listeners.forEach((listener) => listener(order));
  }
}

const orderService = new OrderService();
orderService.subscribe(EmailService.sendShippingEmail);
orderService.subscribe(InventoryService.decrementStock);
orderService.subscribe(AnalyticsService.trackShipment);

// New requirement — just subscribe, OrderService is untouched
orderService.subscribe(SlackNotifier.notifyShipment);
